use vstd::prelude::*;

verus! {
    /// Reverse a non‐empty vector of characters.
    /// 
    /// Requires:
    ///   - arr.len() > 0
    /// Ensures:
    ///   - The output has the same length as the input.
    ///   - For all 0 <= k < arr.len(), outarr[k] == arr[arr.len() - 1 - k].
    fn yarra(arr: &Vec<char>) -> (outarr: Vec<char>)
        requires
            arr.len() > 0,
        ensures
            outarr.len() == arr.len(),
        ensures
            forall |k: usize| k < arr.len() ==> outarr[k] == arr[arr.len() - 1 - k]
    {
        let n = arr.len();
        let mut out: Vec<char> = Vec::new();
        out.reserve(n);
        let mut i: usize = 0;
        // Build the reversed vector one element at a time.
        while i < n
            invariant
                i <= n,
                out.len() == i,
                // so far, out holds the first i elements of the reversal
                forall |k: usize| k < i ==> out[k] == arr[n - 1 - k],
            decreases
                n - i
        {
            let idx = n - 1 - i;
            out.push(arr[idx]);
            i = i + 1;
        }
        out
    }
}

fn main() {
    // Example usage (not part of the verification):
    let v = vec!['a','b','c','d'];
    let r = yarra(&v);
    assert!(r == vec!['d','c','b','a']);
}